"use server";

/**
 * Removes a member (soft delete) and frees the seat.
 *
 * Owner D. The membership row is archived rather than deleted so that issues
 * and comments authored by the person keep resolving their author.
 *
 * Must call (do not reimplement): removeMemberSchema, can, getActor,
 * toActionResult
 */

import { ForbiddenActionError } from "@/actions/_lib/action-errors";
import { withAction } from "@/actions/_lib/with-action";
import { CACHE_PROFILES, orgTag, revalidateTagged } from "@/lib/cache";
import { can } from "@/lib/permissions";
import { removeMemberSchema, type RemoveMemberInput } from "@/schemas/member";
import { removeMember } from "@/server/services/member-service";
import type { ActionResult } from "@/types/api";
import type { Member } from "@/types/member";

const run = withAction<typeof removeMemberSchema, Member>(
  removeMemberSchema,
  async (raw, actor) => {
    const input = raw as RemoveMemberInput;

    const allowed = can(actor, "member:remove", {
      kind: "member",
      orgId: input.orgId,
      memberId: input.memberId,
      targetUserId: actor.userId,
      targetRole: actor.role,
    });
    if (!allowed) {
      throw new ForbiddenActionError("member:remove");
    }

    const member = await removeMember(actor, input);
    revalidateTagged([orgTag(input.orgId)], CACHE_PROFILES.minutes);
    return member;
  },
  { revalidate: ["members"], cacheProfile: "minutes" },
);

export async function removeMemberAction(raw: unknown): Promise<ActionResult<Member>> {
  return run(raw);
}
/**
 * Error types raised by Server Actions that are *expected* failures rather
 * than bugs. Each one carries the `ErrorCode` that `toAppError()` maps into
 * the `AppErrorShape` the client form layer renders, mirroring the convention
 * already used by `PermissionDeniedError` and `TenantScopeError`.
 *
 * These live in `src/actions/_lib` because only the action layer produces
 * them — services throw their own domain errors, and repositories throw none.
 */

import type { LimitedResource } from "@/types/billing";
import type { IsoTimestamp } from "@/types/common";
import type { PermissionAction } from "@/types/permission";

/** No session at all, or a session whose active organization is gone. */
export class UnauthorizedActionError extends Error {
  readonly code = "unauthorized" as const;

  constructor(message = "Sign in to continue.") {
    super(message);
    this.name = "UnauthorizedActionError";
  }
}

/**
 * `can()` returned false. Distinct from `PermissionDeniedError` (thrown by
 * `assertCan()` inside services) only in that the action layer already knows
 * the action name and does not need the full `PermissionDecision`.
 */
export class ForbiddenActionError extends Error {
  readonly code = "forbidden" as const;

  constructor(readonly action: PermissionAction) {
    super(`Permission denied: ${action}`);
    this.name = "ForbiddenActionError";
  }
}

/** A plan quota from `@/config/plan-limits` would be breached. */
export class PlanLimitError extends Error {
  readonly code = "plan_limit_exceeded" as const;

  constructor(
    readonly resource: LimitedResource,
    readonly limit: number,
    readonly used: number,
  ) {
    super(`Plan limit reached for ${resource}: ${used}/${limit}`);
    this.name = "PlanLimitError";
  }
}

/** The token bucket in `@/lib/rate-limit` refused the request. */
export class RateLimitedError extends Error {
  readonly code = "rate_limited" as const;

  constructor(
    readonly bucketKey: string,
    readonly resetAt: IsoTimestamp,
  ) {
    super(`Rate limit exceeded for ${bucketKey}; retry after ${resetAt}`);
    this.name = "RateLimitedError";
  }
}

/** A feature flag that gates the whole action is off for this organization. */
export class FeatureUnavailableError extends Error {
  readonly code = "forbidden" as const;

  constructor(readonly flag: string) {
    super(`Feature not available: ${flag}`);
    this.name = "FeatureUnavailableError";
  }
}

/** The row the action addresses does not exist inside the actor's tenant. */
export class ActionNotFoundError extends Error {
  readonly code = "not_found" as const;

  constructor(readonly what: string) {
    super(`Not found: ${what}`);
    this.name = "ActionNotFoundError";
  }
}
"use client";

/**
 * Members settings table; role and remove controls are permission gated.
 *
 * Must call (do not reimplement): can
 */
import { Avatar } from "@/components/ui/avatar";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeaderCell,
  TableRow,
} from "@/components/ui/table";
import { formatRelative } from "@/lib/date";
import { can } from "@/lib/permissions";
import { isLive } from "@/lib/soft-delete";
import type { MemberId } from "@/types/common";
import type { Actor, MemberWithUser, Role } from "@/types/member";
import type { ReactElement } from "react";
import { memberResource } from "../permission/resources";
import { RoleBadge } from "../permission/role-badge";
import { RoleSelect } from "./role-select";

export type MemberTableProps = {
  members: readonly MemberWithUser[];
  actor: Actor;
  onRoleChange: (memberId: MemberId, role: Role) => void;
  onRemove: (memberId: MemberId) => void;
};

export function MemberTable(props: MemberTableProps): ReactElement | null {
  const { members, actor, onRoleChange, onRemove } = props;
  const visible = members.filter(isLive);

  return (
    <Table caption="Organization members">
      <TableHead>
        <TableRow>
          <TableHeaderCell>Member</TableHeaderCell>
          <TableHeaderCell>Role</TableHeaderCell>
          <TableHeaderCell>Status</TableHeaderCell>
          <TableHeaderCell>Last seen</TableHeaderCell>
          <TableHeaderCell></TableHeaderCell>
        </TableRow>
      </TableHead>

      <TableBody>
        {visible.map((member) => {
          const resource = memberResource(member);
          const mayChangeRole = can(actor, "member:update_role", resource);
          // Nobody removes themselves from the members table; leaving the org
          // is a separate, deliberate flow.
          const isSelf = member.userId === actor.userId;
          const mayRemove = can(actor, "member:remove", resource) && !isSelf;

          return (
            <TableRow key={member.id}>
              <TableCell>
                <span className="flex items-center gap-2">
                  <Avatar
                    name={member.user.name}
                    src={member.user.avatarUrl}
                    size="sm"
                  />
                  <span>
                    <span className="block font-medium">
                      {member.user.name}
                    </span>
                    <span className="block text-xs text-neutral-500">
                      {member.user.email}
                    </span>
                  </span>
                </span>
              </TableCell>

              <TableCell className="w-44">
                {mayChangeRole ? (
                  <RoleSelect
                    value={member.role}
                    actor={actor}
                    onChange={(role) => onRoleChange(member.id, role)}
                  />
                ) : (
                  <RoleBadge role={member.role} />
                )}
              </TableCell>

              <TableCell className="w-32">
                <Badge
                  tone={member.status === "active" ? "success" : "warning"}
                  size="sm"
                >
                  {member.status}
                </Badge>
              </TableCell>

              <TableCell className="w-36 text-sm text-neutral-500">
                {member.lastSeenAt === null
                  ? "Never"
                  : formatRelative(member.lastSeenAt)}
              </TableCell>

              <TableCell className="w-28 text-right">
                {mayRemove ? (
                  <Button
                    variant="danger"
                    size="sm"
                    onClick={() => onRemove(member.id)}
                  >
                    Remove
                  </Button>
                ) : null}
              </TableCell>
            </TableRow>
          );
        })}
      </TableBody>
    </Table>
  );
}
