const OWNER_SCAN_LIMIT = 100;
''', '''/** Input of `suspendMember` and `reinstateMember`. */
export type MemberSuspensionInput = { orgId: OrgId; memberId: MemberId };

/**
 * Raised when work is handed to a suspended member — an issue created with
 * them as assignee, or an existing issue assigned to them. Mapped to
 * `conflict` by callers: the request is well-formed, the member's state is
 * what refuses it.
 */
export class MemberSuspendedError extends Error {
  readonly code = "conflict" as const;

  constructor(readonly userId: UserId) {
    super(`Member ${userId} is suspended and cannot be given new work`);
    this.name = "MemberSuspendedError";
  }
}
