sub(p, '''/**
 * Turns a (user, org) pair into the `Actor` every service method takes.''', '''/**
 * Suspension locks a member out without removing them: the membership, the
 * role and the seat all stay. Idempotent — suspending someone who is already
 * suspended returns them unchanged and publishes nothing.
 */
export async function suspendMember(
  actor: Actor,
  input: MemberSuspensionInput,
): Promise<Member> {
  const member = await requireSuspendableMember(actor, input);
  if (isSuspended(member)) return member;

  // A suspended owner does not keep the workspace ownable, so suspending one
  // is held to the same invariant as demoting or removing them.
  await assertLastOwnerRetained(input.orgId, input.memberId, "member");

  const suspended = await memberRepo.setMemberStatus(
    input.orgId,
    input.memberId,
    "suspended",
  );

  await emit("member.suspended", {
    ...actorEnvelope(actor),
    memberId: suspended.id,
    userId: suspended.userId,
  });

  return suspended;
}

/** Lifts a suspension. Reinstating a member who is not suspended is a no-op. */
export async function reinstateMember(
  actor: Actor,
  input: MemberSuspensionInput,
): Promise<Member> {
  const member = await requireSuspendableMember(actor, input);
  if (!isSuspended(member)) return member;

  const reinstated = await memberRepo.setMemberStatus(
    input.orgId,
    input.memberId,
    "active",
  );

  await emit("member.reinstated", {
    ...actorEnvelope(actor),
    memberId: reinstated.id,
    userId: reinstated.userId,
  });

  return reinstated;
}

/**
 * Throws `MemberSuspendedError` when `userId` is a suspended member of the
 * organization. Anyone else — active, removed, or not a member at all — passes,
 * so the callers' existing behaviour for those cases is untouched.
 */
export async function assertNotSuspended(
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  const member = await memberRepo.findMember(orgId, userId);
  if (member && isSuspended(member)) {
    throw new MemberSuspendedError(userId);
  }
}

/**
 * The guards suspension and reinstatement share. Same shape as removal —
 * tenant scope, a member that is still part of the org, `member:remove` —
 * plus the two rules the permission matrix cannot express: nobody acts on
 * their own membership, and nobody acts on a role that outranks theirs.
 */
async function requireSuspendableMember(
  actor: Actor,
  input: MemberSuspensionInput,
): Promise<Member> {
  assertOrgScope(actor, input.orgId);

  const found = await memberRepo.findMemberById(input.orgId, input.memberId);
  // A removed member keeps a row for the audit log but is no longer a member.
  const member = requireFound(
    found && found.archivedAt === null ? found : null,
    "Member",
    input.memberId,
