/**
 * Suspending and reinstating members: the guards, the last-owner invariant,
 * and everything a suspended member is cut off from while they keep their seat.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { resolveMentions } from "@/lib/mentions";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import { runDigestEmailJob } from "@/server/jobs/digest-email-job";
import { runUsageRollupJob } from "@/server/jobs/usage-rollup-job";
import * as memberRepo from "@/server/repositories/member-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { NotFoundError } from "@/server/services/_support";
import { listActivity, registerActivityListeners } from "@/server/services/activity-service";
import * as commentService from "@/server/services/comment-service";
import { listDigestRecipients } from "@/server/services/digest-service";
import * as emailService from "@/server/services/email-service";
import * as invitationService from "@/server/services/invitation-service";
import * as issueService from "@/server/services/issue-service";
import * as memberService from "@/server/services/member-service";
import { MemberSuspendedError } from "@/server/services/member-service";
import { notify } from "@/server/services/notification-service";
import * as organizationService from "@/server/services/organization-service";
import { resolveActorForOrg } from "@/server/services/session-service";
import { registerUsageListeners } from "@/server/services/usage-service";
import { activityFilterSchema } from "@/schemas/activity";
import { makeMember, makeUser } from "../helpers/factories";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { IsoTimestamp, MemberId, UserId } from "@/types/common";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";
import type { Member, Role } from "@/types/member";

let cleanup: () => void;
const detachers: Unsubscribe[] = [];

function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

async function memberOf(tenant: Tenant, role: Role): Promise<Member> {
  const member = await memberRepo.findMemberById(
    tenant.org.id,
    (await memberIdOf(tenant, role)) as MemberId,
  );
  if (!member) throw new Error("fixture member missing");
  return member;
}

const memberIds = new Map<string, MemberId>();

/** Member ids are looked up once while active — `findMember` hides nobody live. */
async function memberIdOf(tenant: Tenant, role: Role): Promise<MemberId> {
  const key = `${tenant.org.id}:${role}`;
  const known = memberIds.get(key);
  if (known) return known;

  const member = await memberRepo.findMember(tenant.org.id, tenant.userIds[role]);
  if (!member) throw new Error("fixture member missing");
  memberIds.set(key, member.id);
  return member.id;
}

async function suspend(tenant: Tenant, role: Role): Promise<Member> {
  return memberService.suspendMember(tenant.actors.owner, {
    orgId: tenant.org.id,
    memberId: await memberIdOf(tenant, role),
  });
}

async function reinstate(tenant: Tenant, role: Role): Promise<Member> {
  return memberService.reinstateMember(tenant.actors.owner, {
    orgId: tenant.org.id,
    memberId: await memberIdOf(tenant, role),
  });
}

async function unreadFor(tenant: Tenant, userId: UserId): Promise<number> {
  return notificationRepo.countUnread(tenant.org.id, userId);
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
  vi.restoreAllMocks();
  vi.useRealTimers();
});

afterAll(() => {
  cleanup();
});

describe("suspendMember / reinstateMember", () => {
  it("suspends and reinstates, publishing one event each way", async () => {
    const tenant = await createTenant("suspend-roundtrip");
    const suspendedEvents = capture("member.suspended");
    const reinstatedEvents = capture("member.reinstated");

    const suspended = await suspend(tenant, "member");
    expect(suspended.status).toBe("suspended");
    expect(suspended.role).toBe("member");
    expect(suspended.archivedAt).toBeNull();
    expect((await memberOf(tenant, "member")).status).toBe("suspended");

    const reinstated = await reinstate(tenant, "member");
    expect(reinstated.status).toBe("active");
    expect((await memberOf(tenant, "member")).status).toBe("active");

    expect(suspendedEvents).toHaveLength(1);
    expect(suspendedEvents[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.owner,
      memberId: suspended.id,
      userId: tenant.userIds.member,
    });
    expect(reinstatedEvents).toHaveLength(1);
    expect(reinstatedEvents[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.owner,
      memberId: suspended.id,
      userId: tenant.userIds.member,
    });
  });

  it("is a silent no-op when the member is already in the requested state", async () => {
    const tenant = await createTenant("suspend-idempotent");
    await suspend(tenant, "member");

    const suspendedEvents = capture("member.suspended");
    const reinstatedEvents = capture("member.reinstated");

    expect((await suspend(tenant, "member")).status).toBe("suspended");
    expect((await reinstate(tenant, "viewer")).status).toBe("active");

    expect(suspendedEvents).toHaveLength(0);
    expect(reinstatedEvents).toHaveLength(0);
  });

  it("applies the same guards as removal", async () => {
    const tenant = await createTenant("suspend-guards");
    const other = await createTenant("suspend-guards-other");
    const memberId = await memberIdOf(tenant, "viewer");
    const events = capture("member.suspended");

    for (const act of [memberService.suspendMember, memberService.reinstateMember]) {
      await expect(
        act(tenant.actors.owner, { orgId: other.org.id, memberId }),
      ).rejects.toBeInstanceOf(TenantScopeError);

      await expect(
        act(tenant.actors.owner, {
          orgId: tenant.org.id,
          memberId: await memberIdOf(other, "viewer"),
        }),
      ).rejects.toBeInstanceOf(NotFoundError);

      await expect(
        act(tenant.actors.member, { orgId: tenant.org.id, memberId }),
      ).rejects.toBeInstanceOf(PermissionDeniedError);
    }

    expect(events).toHaveLength(0);
    expect((await memberOf(tenant, "viewer")).status).toBe("active");
  });

  it("treats a removed member as not found, never as suspended", async () => {
    const tenant = await createTenant("suspend-removed");
    const memberId = await memberIdOf(tenant, "viewer");
    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId,
    });

    await expect(
      memberService.suspendMember(tenant.actors.owner, { orgId: tenant.org.id, memberId }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      memberService.reinstateMember(tenant.actors.owner, { orgId: tenant.org.id, memberId }),
    ).rejects.toBeInstanceOf(NotFoundError);

    const suspendedList = await memberService.listMembers(tenant.actors.owner, {
      orgId: tenant.org.id,
      status: "suspended",
      limit: 25,
      cursor: null,
    });
    expect(suspendedList.items).toHaveLength(0);
    await expect(memberRepo.countActiveMembers(tenant.org.id)).resolves.toBe(3);
  });

  it("refuses self-suspension and acting on a higher role", async () => {
    const tenant = await createTenant("suspend-rank");
    const events = capture("member.suspended");

    await expect(
      memberService.suspendMember(tenant.actors.admin, {
        orgId: tenant.org.id,
        memberId: await memberIdOf(tenant, "admin"),
      }),
    ).rejects.toThrow();

    await expect(
      memberService.suspendMember(tenant.actors.admin, {
        orgId: tenant.org.id,
        memberId: await memberIdOf(tenant, "owner"),
      }),
    ).rejects.toThrow();

    expect(events).toHaveLength(0);
    expect((await memberOf(tenant, "admin")).status).toBe("active");
    expect((await memberOf(tenant, "owner")).status).toBe("active");

    // Reinstatement is held to the same two rules.
    await suspend(tenant, "admin");
    await expect(
      memberService.reinstateMember(tenant.actors.admin, {
        orgId: tenant.org.id,
        memberId: await memberIdOf(tenant, "admin"),
      }),
    ).rejects.toThrow();
    expect((await memberOf(tenant, "admin")).status).toBe("suspended");

    // An admin may suspend a peer or anyone below.
    const suspended = await memberService.suspendMember(tenant.actors.admin, {
      orgId: tenant.org.id,
      memberId: await memberIdOf(tenant, "member"),
    });
    expect(suspended.status).toBe("suspended");
  });

  it("keeps at least one owner who is not suspended", async () => {
    const tenant = await createTenant("suspend-last-owner");
    const ownerId = await memberIdOf(tenant, "owner");
    const secondId = await memberIdOf(tenant, "admin");

    await memberService.updateMemberRole(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: secondId,
      role: "owner",
    });
    const second = { ...tenant.actors.admin, role: "owner" as const };

    await memberService.suspendMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: secondId,
    });

    // The suspended owner no longer keeps the workspace ownable.
    await expect(
      memberService.suspendMember(second, { orgId: tenant.org.id, memberId: ownerId }),
    ).rejects.toThrow(/at least one owner/);
    await expect(
      memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: ownerId,
        role: "admin",
      }),
    ).rejects.toThrow(/at least one owner/);
    await expect(
      memberService.removeMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: ownerId,
      }),
    ).rejects.toThrow(/at least one owner/);

    await memberService.reinstateMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: secondId,
    });

    const demoted = await memberService.updateMemberRole(second, {
      orgId: tenant.org.id,
      memberId: ownerId,
      role: "admin",
    });
    expect(demoted.role).toBe("admin");
  });

  it("writes one audit row per suspension and reinstatement", async () => {
    const tenant = await createTenant("suspend-audit");
    detachers.push(registerActivityListeners());

    const suspended = await suspend(tenant, "member");
    await reinstate(tenant, "member");

    const filter = activityFilterSchema.parse({
      orgId: tenant.org.id,
      action: ["member.suspended", "member.reinstated"],
      limit: 25,
    });
    const page = await listActivity(tenant.actors.owner, filter);

    expect(page.items.map((row) => row.action).sort()).toEqual([
      "member.reinstated",
      "member.suspended",
    ]);
    for (const row of page.items) {
      expect(row).toMatchObject({
        actorId: tenant.userIds.owner,
        subjectKind: "member",
        subjectId: suspended.id,
      });
    }
  });
});

describe("while a member is suspended", () => {
  it("resolves no actor and drops the workspace from the org switcher", async () => {
    const tenant = await createTenant("suspended-access");
    const principal = {
      userId: tenant.userIds.member,
      email: "member@suspended-access.test",
      activeOrgId: tenant.org.id,
      expiresAt: "2099-01-01T00:00:00.000Z" as IsoTimestamp,
    };

    await suspend(tenant, "member");

    await expect(
      memberService.resolveActor(tenant.userIds.member, tenant.org.id),
    ).resolves.toBeNull();
    await expect(resolveActorForOrg(principal, tenant.org.slug)).resolves.toBeNull();
    await expect(
      organizationService.listOrganizationsForUser(tenant.userIds.member),
    ).resolves.toEqual([]);

    await reinstate(tenant, "member");

    await expect(
      memberService.resolveActor(tenant.userIds.member, tenant.org.id),
    ).resolves.toMatchObject({ role: "member" });
    const orgs = await organizationService.listOrganizationsForUser(tenant.userIds.member);
    expect(orgs.map((org) => org.id)).toEqual([tenant.org.id]);
  });

  it("keeps the seat in every seat count; removal still frees it", async () => {
    const tenant = await createTenant("suspended-seats", "free");
    await usageRepo.recomputeUsage(tenant.org.id);
    detachers.push(registerUsageListeners());

    await suspend(tenant, "viewer");

    await expect(memberRepo.countActiveMembers(tenant.org.id)).resolves.toBe(4);
    expect((await usageRepo.getUsage(tenant.org.id)).seatsUsed).toBe(4);
    expect((await usageRepo.recomputeUsage(tenant.org.id)).seatsUsed).toBe(4);
    await runUsageRollupJob(new Date());
    expect((await usageRepo.getUsage(tenant.org.id)).seatsUsed).toBe(4);

    const summary = await organizationService.getOrganizationSummary(
      tenant.actors.owner,
      tenant.org.id,
    );
    expect(summary.memberCount).toBe(4);

    // Free allows three seats; the suspended member still occupies theirs.
    await expect(
      invitationService.inviteMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        email: "new@suspended-seats.test",
        role: "member",
      }),
    ).rejects.toThrow(/seats/);

    const listed = await memberService.listMembers(tenant.actors.owner, {
      orgId: tenant.org.id,
      limit: 25,
      cursor: null,
    });
    expect(
      listed.items.find((row) => row.userId === tenant.userIds.viewer)?.status,
    ).toBe("suspended");

    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: await memberIdOf(tenant, "viewer"),
    });
    await expect(memberRepo.countActiveMembers(tenant.org.id)).resolves.toBe(3);
    expect((await usageRepo.getUsage(tenant.org.id)).seatsUsed).toBe(3);
    expect((await usageRepo.recomputeUsage(tenant.org.id)).seatsUsed).toBe(3);
  });

  it("creates no notification for them, by fan-out or by notify()", async () => {
    const tenant = await createTenant("suspended-notify");
    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Already theirs",
        assigneeId: tenant.userIds.member,
      }),
    );

    await suspend(tenant, "member");
    const before = await unreadFor(tenant, tenant.userIds.member);

    const direct = await notify(
      tenant.org.id,
      "issue_assigned",
      [tenant.userIds.member, tenant.userIds.admin],
      { title: "Direct", body: "Direct", href: "/issues/1", actorId: tenant.userIds.owner },
    );
    expect(direct.map((row) => row.recipientId)).toEqual([tenant.userIds.admin]);

    // A comment on their issue would normally notify the assignee.
