    await runDigestEmailJob(now);
    expect(sendSpy).toHaveBeenCalledTimes(1);
    expect(await unreadFor(tenant, tenant.userIds.member)).toBe(0);
  });

  it("refuses to hand them new work but leaves existing work alone", async () => {
    const tenant = await createTenant("suspended-assign");
    const theirs = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Assigned before",
        assigneeId: tenant.userIds.member,
      }),
    );
    const open = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "Unassigned" }),
    );

    await suspend(tenant, "member");

    const created = capture("issue.created");
    const assigned = capture("issue.assigned");
    const updated = capture("issue.updated");
    const countBefore = (
      await issueService.listIssues(tenant.actors.owner, {
        orgId: tenant.org.id,
        limit: 25,
        cursor: null,
      })
    ).total;

    const refusedCreate = issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "For a suspended member",
        assigneeId: tenant.userIds.member,
      }),
    );
    await expect(refusedCreate).rejects.toBeInstanceOf(MemberSuspendedError);
    await expect(refusedCreate).rejects.toMatchObject({ code: "conflict" });

    await expect(
      issueService.assignIssue(tenant.actors.owner, {
        orgId: tenant.org.id,
        issueId: open.id,
        assigneeId: tenant.userIds.member,
      }),
    ).rejects.toBeInstanceOf(MemberSuspendedError);

    expect(created).toHaveLength(0);
    expect(assigned).toHaveLength(0);
    expect(
      (
        await issueService.listIssues(tenant.actors.owner, {
          orgId: tenant.org.id,
          limit: 25,
          cursor: null,
        })
      ).total,
    ).toBe(countBefore);

    const stillOpen = await issueService.getIssue(tenant.actors.owner, tenant.org.id, open.id);
    expect(stillOpen.issue.assigneeId).toBeNull();
    const stillTheirs = await issueService.getIssue(tenant.actors.owner, tenant.org.id, theirs.id);
    expect(stillTheirs.issue.assigneeId).toBe(tenant.userIds.member);

    // Assigning to an active member and un-assigning work as before.
    await issueService.assignIssue(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: open.id,
      assigneeId: tenant.userIds.admin,
    });
    await issueService.assignIssue(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: theirs.id,
      assigneeId: null,
    });
    expect(assigned).toHaveLength(1);
    expect(updated).toHaveLength(1);

    await reinstate(tenant, "member");
    const reassigned = await issueService.assignIssue(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: theirs.id,
      assigneeId: tenant.userIds.member,
    });
    expect(reassigned.assigneeId).toBe(tenant.userIds.member);
  });

  it("cannot be mentioned by handle or by a client-supplied id", async () => {
    const tenant = await createTenant("suspended-mention");
    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "Discuss" }),
    );
    await suspend(tenant, "member");

    const seen = capture("comment.created");
    const comment = await commentService.createComment(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "cc @member and @admin",
      parentId: null,
      mentionedUserIds: [tenant.userIds.member, tenant.userIds.viewer],
    });

    const expected = [tenant.userIds.admin, tenant.userIds.viewer];
    expect([...comment.mentionedUserIds].sort()).toEqual([...expected].sort());
    expect([...(seen[0]?.mentionedUserIds ?? [])].sort()).toEqual([...expected].sort());
    expect(await unreadFor(tenant, tenant.userIds.member)).toBe(0);

    await reinstate(tenant, "member");
    const after = await commentService.createComment(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "back to @member",
      parentId: null,
      mentionedUserIds: [],
    });
    expect(after.mentionedUserIds).toEqual([tenant.userIds.member]);
  });

  it("does not resolve a suspended member's handle in resolveMentions", () => {
    const bob = makeUser({ id: "01HZZZBBBBBBBBBBBBBBBBBBB2" as UserId, email: "bob@example.com" });
    const members = [
      makeMember({ user: makeUser() }),
      makeMember({ user: bob, status: "suspended" }),
    ];

    expect(resolveMentions("@alice @bob", members)).toEqual([members[0]?.userId]);
  });
});

